def _create_table(name, *columns, **kwargs):
    if op.get_context().as_sql or not sa.inspect(op.get_bind()).has_table(name):
        return op.create_table(name, *columns, **kwargs)
    expected = {c.name for c in columns if isinstance(c, sa.Column)}
    existing = {c["name"] for c in sa.inspect(op.get_bind()).get_columns(name)}
    if not expected.issubset(existing):
        raise RuntimeError(f"Existing table {name} has an incompatible schema")


def _create_index(name, table_name, columns, **kwargs):
    if not op.get_context().as_sql:
        existing = {i["name"] for i in sa.inspect(op.get_bind()).get_indexes(table_name)}
        if name in existing:
            return
    op.create_index(name, table_name, columns, **kwargs)


